// Handle both n8n test shape ({body:{...}}) and raw Vapi POST ({message:{...}})
const payload = $input.first().json;
const body = payload.body ?? payload;

const message = body.message ?? {};
const toolCall = (message.toolCallList && message.toolCallList[0])
  ?? (message.toolCalls && message.toolCalls[0])
  ?? {};

// Vapi may send function.arguments as a JSON STRING or an object.
const rawArgs = toolCall.function?.arguments ?? {};
let args = {};
try {
  args = typeof rawArgs === 'string' ? JSON.parse(rawArgs) : (rawArgs || {});
} catch (e) {
  args = {};
}

// Accept BOTH naming conventions (long prompt names and short schema names).
const pick = (...keys) => {
  for (const k of keys) {
    const v = args[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return undefined;
};

const str = v => (v === undefined || v === null) ? '' : String(v).trim();

const rawBudget = pick('budget_pkr', 'budget');

return [{
  json: {
    toolCallId: toolCall.id || '',
    client_name: str(pick('client_name', 'name')),
    company: str(pick('company_name', 'company')),
    email: str(pick('email')),
    service: str(pick('service_required', 'service')),
    description: str(pick('project_description', 'description')),
    budget: (rawBudget === undefined) ? null : Number(rawBudget),
  }
}];

