// Works with either classifier feeding this node:
// - LangChain AI Agent outputs to $json.output
// - OpenAI HTTP node outputs to $json.choices[0].message.content
const inp = $input.first().json;
let raw = inp.output ?? inp.choices?.[0]?.message?.content ?? '';

if (typeof raw !== 'string') raw = JSON.stringify(raw);

raw = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

const ai = JSON.parse(raw);
return [{ json: ai }];

const intake = $('Normalize intake').first().json;
const ai = $input.first().json;

const budgetNum = (intake.budget === null || intake.budget === undefined || isNaN(Number(intake.budget)))
  ? null
  : Number(intake.budget);

let priority = 'LOW';
if (budgetNum !== null && budgetNum >= 500000) priority = 'HIGH';
else if (budgetNum !== null && budgetNum >= 200000) priority = 'MEDIUM';

// Guarantee a non-empty title source for Notion (title cannot be undefined/empty).
const safe = (v, fallback) => {
  const s = (v === undefined || v === null) ? '' : String(v).trim();
  return s.length ? s : fallback;
};

const client_name = safe(intake.client_name, 'Unknown Client');
const company = safe(intake.company, client_name); // title falls back to client, then to a literal below
const titleValue = safe(company, safe(client_name, 'Unknown Client'));

return [{
  json: {
    toolCallId: intake.toolCallId || '',
    client_name,
    company,
    title: titleValue,
    email: safe(intake.email, ''),
    service: safe(intake.service, 'Not provided'),
    description: safe(intake.description, 'Not provided'),
    budget: budgetNum,
    budget_display: budgetNum === null ? 'Not provided' : String(budgetNum),
    category: safe(ai.service_category, 'Other'),
    priority: priority,
    summary: safe(ai.summary, 'No summary available.'),
    next_action: safe(ai.next_action, 'Follow up with the client for missing details.'),
    status: 'New',
    created_at: new Date().toISOString(),
  }
}];

// Runs after Airtable + Notion (both may have failed soft via continueRegularOutput).
const data = $('Compute priority + merge').first().json;

function ok(nodeName, successTest) {
  try {
    const out = $(nodeName).first().json;
    if (out && out.error) return false;
    return successTest(out);
  } catch (e) {
    return false;
  }
}

const airtableOk = ok('Create a record', o => !!(o && (o.id || o.fields)));
const notionOk   = ok('Create a page',   o => !!(o && o.id));

const mark = b => (b ? '\u2705' : '\u26a0\ufe0f');
const airtableLine = `${mark(airtableOk)} Airtable ${airtableOk ? 'record created' : 'FAILED'}`;
const notionLine   = `${mark(notionOk)} Notion ${notionOk ? 'page created' : 'FAILED'}`;

const slackText = [
  `:phone: *New client intake \u2014 ${data.priority} priority*`,
  `*Client:* ${data.client_name} (${data.company})`,
  `*Service:* ${data.category}`,
  `*Summary:* ${data.summary}`,
  `*Next action:* ${data.next_action}`,
  `*Email:* ${data.email}  |  *Budget:* ${data.budget} PKR`,
  ``,
  `*Records:*  ${airtableLine}   ${notionLine}`
].join('\n');

return [{
  json: {
    ...data,
    airtable_ok: airtableOk,
    notion_ok: notionOk,
    slack_text: slackText,
  }
}];
